def source_sort_key(row):
    import unicodedata
    name = unicodedata.normalize("NFKD", row[0]).casefold()
    name = "".join(c for c in name if not unicodedata.combining(c))
    return CATEGORIES.index(row[1]), name

ROWS.sort(key=source_sort_key)


