def comparison_meta(row):
    name,category=row[:2]
    access='Not verified' if name in UNVERIFIED else 'Paid' if name in PAID else 'Partial' if name in PARTIAL else 'Open'
    return LANGUAGES.get(name,'English'), TYPE_OVERRIDES.get(name,CONTENT_TYPES[category]), access

