    css += """.editorial-footer{padding:44px 0 28px}.footer-main{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:start}.footer-wordmark{display:block;font:30px/1.1 'Instrument Serif',Georgia,serif;letter-spacing:.06em;color:var(--ink)}.footer-brand p{font-size:14px;line-height:1.6;margin:14px 0 0;color:var(--muted)}.footer-nav{display:grid;grid-template-columns:1fr 1fr;gap:2px 24px}.footer-nav a{display:inline-flex;align-items:center;min-height:44px;font-size:13px;text-decoration:none}.footer-nav a:hover{text-decoration:underline}.footer-meta{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:24px;margin-top:30px;font-size:11px;letter-spacing:.07em}.footer-context,.footer-colophon{max-width:90ch;font-size:12px;line-height:1.7;margin:16px 0 0}.footer-colophon{font-size:11px}@media(max-width:650px){.editorial-footer{padding-top:32px}.footer-main{grid-template-columns:1fr;gap:24px}.footer-nav{gap:0 18px}.footer-meta{gap:8px;margin-top:24px}}@media print{.footer-nav{display:none}.footer-main{grid-template-columns:1fr}.editorial-footer{padding-top:20px}.footer-wordmark{font-size:24px}.footer-context,.footer-colophon,.footer-meta{font-size:9px}}"""
